#!/usr/bin/env python3
import importlib.util, json, random, sys, copy

def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod

main = load("/workspace/submission/main.py", "mainmod")
ref = load("/workspace/tmp/dev/ref.py", "refmod")

class Invalid(Exception):
    pass

def run_ref(doc):
    try:
        return ref.solve(copy.deepcopy(doc))
    except Exception:
        return {"error": "invalid-input"}

def run_main(doc):
    try:
        return main._solve(copy.deepcopy(doc))
    except main.Invalid:
        return {"error": "invalid-input"}

def rnd_model(r, C=None, E=None, K=None, W=None):
    C = C or r.randint(2, 8)
    E = E or r.randint(1, 4)
    K = K or r.randint(1, 5)
    if W is not None and K > W:
        K = r.randint(1, W)
    F = r.randint(1, 8)
    def emb():
        return [[r.choice([-128, -127, -1, 0, 1, 2, 63, 126, 127, r.randint(-128, 127)]) for _ in range(E)] for _ in range(16)]
    return {
        "classes": C, "embedding_dim": E,
        "length_embedding": emb(), "gap_embedding": emb(),
        "kernel": K,
        "conv_weights": [[[r.choice([-128,-1,0,1,127,r.randint(-128,127)]) for _ in range(2*E)] for _ in range(K)] for _ in range(F)],
        "conv_bias": [r.choice([0, r.randint(-2**31, 2**31-1), r.randint(-1000,1000)]) for _ in range(F)],
        "conv_shift": [r.randint(0,16) for _ in range(F)],
        "dense_weights": [[r.choice([-128,-1,0,1,127,r.randint(-128,127)]) for _ in range(F)] for _ in range(C)],
        "dense_bias": [r.choice([0, r.randint(-2**31, 2**31-1), r.randint(-100,100)]) for _ in range(C)],
    }

def rnd_config(r, C, K, W=None):
    S = r.choice([1, 2, 3, r.randint(1, 8), r.randint(1, 256)])
    W = W or r.randint(max(K,1), 16)
    nte = r.randint(1, 4)
    nce = r.randint(1, 4)
    te = [0]
    while len(te) < nte:
        te.append(te[-1] + r.choice([1, 2, 5, 17, 1000]))
    ce = [0]
    while len(ce) < nce:
        ce.append(ce[-1] + r.choice([1, 2, 3, 7]))
    return {
        "slots": S, "window": W,
        "idle_timeout": r.choice([1, 2, 3, 5, 10, 100, 10**12, r.randint(1,10**6)]),
        "len_quantum": r.choice([1, 1, 2, 3, 7, 100, 4096, 65535, r.randint(1,65535)]),
        "gap_quantum": r.choice([1, 1, 2, 5, 65535, r.randint(1,65535)]),
        "rate_num": r.choice([1, 1, 2, 3, 7, 10**6, r.randint(1,10**6)]),
        "rate_den": r.choice([1, 1, 2, 3, 5, 7, 1000, 10**6, r.randint(1,10**6)]),
        "bucket_capacity": r.choice([1, 1, 2, 3, 8, 512, r.randint(1,512)]),
        "initial_tokens": 0,
        "pending_capacity": r.choice([1, 1, 2, 3, 512, r.randint(1,512)]),
        "lanes": r.choice([1, 1, 2, 3, 4]),
        "service": [r.choice([1, 2, 3, 5, 11, 10**6, r.randint(1,10**6)]) for _ in range(C)],
        "fallback": r.randint(0, C-1),
        "time_edges": te, "count_edges": ce,
        "probability": [[r.choice([0, 1, 32768, 65535, 65536, r.randint(0,65536)]) for _ in range(nce)] for _ in range(nte)],
    }

def rnd_case(r, npkt=None, nconn=None):
    C = r.randint(2, 8)
    E = r.randint(1, 4)
    K = r.randint(1, 5)
    model = rnd_model(r, C, E, K)
    W = model["kernel"]
    cfg = rnd_config(r, C, K, r.randint(K, 16))
    cfg["initial_tokens"] = r.randint(0, cfg["bucket_capacity"])
    nconn = nconn if nconn is not None else r.choice([0, 1, 2, 3, 5, r.randint(1, 12)])
    conns = []
    used = set()
    for i in range(nconn):
        cid = r.choice(["a", "b", "c%d" % i, "x_" + str(i), "A" * r.randint(1, 5), "%s-%d" % (r.choice("qQz9_-"), i)])
        if cid in used:
            cid = cid + "u" + str(i)
        used.add(cid)
        conns.append({"id": cid, "slot": r.randint(0, cfg["slots"] - 1),
                      "label": r.randint(0, C - 1), "split": r.choice(["dev", "eval"])})
    npkt = npkt if npkt is not None else r.choice([0, 1, 2, 5, 20, 60, r.randint(0, 120)])
    pkts = []
    t = r.choice([0, 0, 1, 5, 1000])
    for i in range(npkt):
        if conns:
            cid = r.choice(conns)["id"]
        else:
            cid = "zz"
        t = t + r.choice([0, 0, 0, 1, 1, 2, 3, 5, 11, 100, r.randint(0, 50)])
        pkts.append({"time": t, "connection": cid,
                     "length": r.choice([0, 1, 15, 16, 255, 65535, r.randint(0, 65535)]),
                     "draw": r.choice([0, 1, 32768, 65535, r.randint(0, 65535)])})
    return {"version": 1, "config": cfg, "model": model, "connections": conns, "packets": pkts}

def compare(doc, tag):
    a = run_main(doc)
    b = run_ref(doc)
    if a != b:
        print("MISMATCH", tag)
        print(json.dumps(doc)[:4000])
        # locate difference
        if isinstance(a, dict) and isinstance(b, dict) and set(a) == set(b):
            for k in a:
                if a[k] != b[k]:
                    print("key", k)
                    if isinstance(a[k], list):
                        for i, (x, y) in enumerate(zip(a[k], b[k])):
                            if x != y:
                                print(" ", i, json.dumps(x), json.dumps(y))
                                break
                        if len(a[k]) != len(b[k]):
                            print("  len", len(a[k]), len(b[k]))
                    else:
                        print(" ", json.dumps(a[k])[:1000], json.dumps(b[k])[:1000])
        else:
            print(" main:", json.dumps(a)[:500])
            print(" ref :", json.dumps(b)[:500])
        with open("/workspace/tmp/dev/fail_%s.json" % tag, "w") as fh:
            json.dump(doc, fh)
        return False
    return True

def main_loop(n, seed0=0):
    r = random.Random(seed0)
    bad = 0
    for i in range(n):
        doc = rnd_case(r)
        if not compare(doc, "s%d_%d" % (seed0, i)):
            bad += 1
            if bad > 3:
                break
    print("done seed", seed0, "cases", n, "mismatches", bad)
    return bad

if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    s = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    sys.exit(1 if main_loop(n, s) else 0)
